+package org.dependencytrack.frontend;
+
+import { useState, useEffect } from 'react';
+import DOMPurify from 'dompurify';
+
+export function LoginPage() {
+  const [welcomeMessage, setWelcomeMessage] = useState('');
+  
+  useEffect(() => {
+    // Fetch welcome message from configuration
+    fetch('/api/v1/config/welcomeMessage')
+      .then(res => res.text())
+      .then(text => setWelcomeMessage(text))
+      .catch(err => console.error('Failed to load welcome message:', err));
+  }, []);
+
+  // Sanitize the welcome message to prevent XSS
+  const sanitizedWelcomeMessage = DOMPurify.sanitize(welcomeMessage, {
+    ALLOWED_TAGS: ['b', 'i', 'u', 'em', 'strong', 'a', 'p', 'br', 'span'],
+    ALLOWED_ATTR: ['href', 'class', 'style']
+  });
+
+  return (
+    <div className="login-page">
+      <div 
+        className="welcome-message"
+        dangerouslySetInnerHTML={{ __html: sanitizedWelcomeMessage }}
+      />
+      {/* rest of login form */}
+    </div>
+  );
+}

